1	# Backfill TikTok order SKUs from PG order_id list → detail page → tiktok_order_lines
2	# Usage:
3	#   powershell -ExecutionPolicy Bypass -File .\scripts\fill-order-skus.ps1
4	#   powershell -ExecutionPolicy Bypass -File .\scripts\fill-order-skus.ps1 -MaxPerStore 20
5	#   powershell -ExecutionPolicy Bypass -File .\scripts\fill-order-skus.ps1 -CsvPath .\logs\missing-order-sku.csv -DryRun true
6	
7	param(
8	  [string]$ConfigPath = "",
9	  [string]$CsvPath = "",
10	  [int]$MaxPerStore = 0,
11	  [int]$DetailWaitMs = 3200,
12	  [int]$StartOffset = 0,
13	  [string]$OnlyStoreId = "",
14	  [string]$DryRun = ""
15	)
16	
17	$ErrorActionPreference = 'Stop'
18	$PSNativeCommandUseErrorActionPreference = $false
19	$root = Split-Path $PSScriptRoot -Parent
20	if (-not $ConfigPath) { $ConfigPath = Join-Path $root 'config\stores.config.json' }
21	$detailJsPath = Join-Path $root 'scripts\scrape-order-detail-page.js'
22	if (-not (Test-Path $ConfigPath)) { throw "Missing config: $ConfigPath" }
23	if (-not (Test-Path $detailJsPath)) { throw "Missing $detailJsPath" }
24	if (-not $CsvPath) { $CsvPath = Join-Path $root 'logs\missing-order-sku.csv' }
25	if (-not (Test-Path $CsvPath)) { throw "Missing order CSV: $CsvPath (export from PG first)" }
26	
27	$cfg = Get-Content $ConfigPath -Raw -Encoding UTF8 | ConvertFrom-Json
28	$detailJs = Get-Content $detailJsPath -Raw -Encoding UTF8
29	$qingquanLib = Join-Path $PSScriptRoot 'qingquan-client.ps1'
30	if (Test-Path $qingquanLib) { . $qingquanLib }
31	$ziniaoWinLib = Join-Path $PSScriptRoot 'ziniao-window.ps1'
32	if (-not (Test-Path $ziniaoWinLib)) { throw "Missing $ziniaoWinLib" }
33	. $ziniaoWinLib
34	
35	$script:logsDir = Join-Path $root 'logs'
36	New-Item -ItemType Directory -Force -Path $script:logsDir | Out-Null
37	$script:runStamp = Get-Date -Format 'yyyyMMdd-HHmmss'
38	$script:runLogFile = Join-Path $script:logsDir ("fill-order-sku-{0}.log" -f $script:runStamp)
39	
40	function Write-RunLog([string]$msg) {
41	  $line = "[{0}] {1}" -f (Get-Date -Format 'yyyy-MM-dd HH:mm:ss'), $msg
42	  try { Add-Content -LiteralPath $script:runLogFile -Value $line -Encoding UTF8 } catch { }
43	}
44	function Write-Step([string]$msg) {
45	  Write-Host ("[{0}] {1}" -f (Get-Date -Format 'HH:mm:ss'), $msg)
46	  Write-RunLog $msg
47	}
48	function ConvertTo-ProcessArgument([string]$s) {
49	  if ($null -eq $s) { return '""' }
50	  if ($s -match '[\s"]') { return '"' + ($s -replace '"', '\"') + '"' }
51	  return $s
52	}
53	function Initialize-ZiniaoCli {
54	  if ($script:ZiniaoNode) { return }
55	  $node = (Get-Command node -ErrorAction SilentlyContinue).Source
56	  if (-not $node) { throw 'node not found' }
57	  $runJs = Join-Path $env:APPDATA 'npm\node_modules\@ziniao-open\cli\scripts\run.js'
58	  if (-not (Test-Path $runJs)) {
59	    $cmd = Get-Command ziniao -ErrorAction SilentlyContinue
60	    if ($cmd) { $runJs = $cmd.Source }
61	  }
62	  if (-not (Test-Path $runJs)) { throw 'ziniao-cli run.js not found' }
63	  $script:ZiniaoNode = $node
64	  $script:ZiniaoRunJs = $runJs
65	}
66	function Invoke-Ziniao([string[]]$CliArgs) {
67	  Initialize-ZiniaoCli
68	  $utf8 = [System.Text.UTF8Encoding]::new($false)
69	  $allArgs = @($script:ZiniaoRunJs) + @($CliArgs)
70	  $argLine = ($allArgs | ForEach-Object { ConvertTo-ProcessArgument ([string]$_) }) -join ' '
71	  $psi = New-Object System.Diagnostics.ProcessStartInfo
72	  $psi.FileName = $script:ZiniaoNode
73	  $psi.Arguments = $argLine
74	  $psi.UseShellExecute = $false
75	  $psi.RedirectStandardOutput = $true
76	  $psi.RedirectStandardError = $true
77	  $psi.CreateNoWindow = $true
78	  $psi.StandardOutputEncoding = $utf8
79	  $psi.StandardErrorEncoding = $utf8
80	  $p = New-Object System.Diagnostics.Process
81	  $p.StartInfo = $psi
82	  [void]$p.Start()
83	  $stdout = $p.StandardOutput.ReadToEnd()
84	  $stderr = $p.StandardError.ReadToEnd()
85	  $p.WaitForExit()
86	  if ($stderr -and $stderr.Trim()) { Write-RunLog ("ziniao stderr: {0}" -f $stderr.Trim()) }
87	  return $stdout
88	}
89	function ConvertTo-ScrapeOneLine([string]$js) {
90	  $one = ($js -replace '(?m)^\s*//.*$', '' -replace '\r?\n', ' ' -replace '\s+', ' ').Trim()
91	  return $one
92	}
93	function Get-OrdersUrl($store, $cfg) {
94	  $plat = ''
95	  if ($store.platformName) { $plat = [string]$store.platformName }
96	  elseif ($store.platform) { $plat = [string]$store.platform }
97	  if ($cfg.orderUrl -and $cfg.orderUrl.byPlatform -and $plat) {
98	    foreach ($p in $cfg.orderUrl.byPlatform.PSObject.Properties) {
99	      if ($plat -eq [string]$p.Name -or $plat -like ("*{0}*" -f $p.Name) -or ([string]$p.Name -like ("*{0}*" -f $plat))) {
100	        return [string]$p.Value
101	      }
102	    }
103	  }
104	  if ($cfg.orderUrl -and $cfg.orderUrl.default) { return [string]$cfg.orderUrl.default }
105	  return 'https://seller-uk.tiktok.com/order?selected_sort=6&tab=all'
106	}
107	function Get-OrderDetailBaseUrl([string]$orderListUrl) {
108	  try {
109	    $u = [uri]$orderListUrl
110	    $origin = "{0}://{1}" -f $u.Scheme, $u.Host
111	    return ($origin.TrimEnd('/') + '/order/detail')
112	  } catch {
113	    return 'https://seller-uk.tiktok.com/order/detail'
114	  }
115	}
116	function Get-OrderRegionQuery([string]$orderListUrl) {
117	  if ($orderListUrl -match 'shop_region=([A-Za-z]{2})') { return $Matches[1] }
118	  if ($orderListUrl -match 'seller-uk') { return 'GB' }
119	  return 'GB'
120	}
121	function Get-DisplayName($store, $map) {
122	  $n = [string]$store.storeName
123	  if ($map -and $map.PSObject.Properties.Name -contains $n) { return [string]$map.$n }
124	  return $n
125	}
126	function Get-ScrapePayload([string]$execOut) {
127	  if ([string]::IsNullOrWhiteSpace($execOut)) { return $null }
128	  try {
129	    $j = $execOut | ConvertFrom-Json
130	    if ($j.data -and $j.data.data -and $j.data.data.result) {
131	      $inner = [string]$j.data.data.result
132	      return ($inner | ConvertFrom-Json)
133	    }
134	    if ($null -ne $j.ok) { return $j }
135	  } catch { }
136	  $m = [regex]::Matches($execOut, '\{(?:[^{}]|(?<o>\{)|(?<-o>\}))+(?(o)(?!))\}')
137	  if ($m.Count -gt 0) {
138	    try { return ($m[$m.Count - 1].Value | ConvertFrom-Json) } catch { }
139	  }
140	  return $null
141	}
142	function Convert-DryRunFlag([string]$raw) {
143	  if ([string]::IsNullOrWhiteSpace($raw)) { return $null }
144	  switch -Regex ($raw.Trim()) {
145	    '^(?i:true|1|yes|y|\$true)$'  { return $true }
146	    '^(?i:false|0|no|n|\$false)$' { return $false }
147	    default { throw "Invalid -DryRun '$raw'" }
148	  }
149	}
150	
151	Write-Step '===== fill order SKU START ====='
152	Write-Step ("csv={0}" -f $CsvPath)
153	$rows = @(Import-Csv -LiteralPath $CsvPath -Encoding UTF8)
154	if ($rows.Count -eq 0) { throw 'CSV empty' }
155	# normalize columns
156	$normRows = New-Object System.Collections.ArrayList
157	foreach ($r in $rows) {
158	  $sid = ''
159	  if ($r.shop_external_id) { $sid = [string]$r.shop_external_id }
160	  elseif ($r.storeId) { $sid = [string]$r.storeId }
161	  elseif ($r.shop_id) { $sid = [string]$r.shop_id }
162	  $oid = ''
163	  if ($r.order_id) { $oid = [string]$r.order_id }
164	  elseif ($r.orderId) { $oid = [string]$r.orderId }
165	  $sname = ''
166	  if ($r.shop_name) { $sname = [string]$r.shop_name }
167	  elseif ($r.shopName) { $sname = [string]$r.shopName }
168	  if (-not $sid -or -not $oid) { continue }
169	  if ($OnlyStoreId -and $sid -ne $OnlyStoreId) { continue }
170	  [void]$normRows.Add([pscustomobject]@{ storeId = $sid; orderId = $oid; shopName = $sname })
171	}
172	Write-Step ("targets total={0}" -f $normRows.Count)
173	if ($normRows.Count -eq 0) { throw 'No target rows after filter' }
174	
